import{_ as t,c as n,o as l,j as e,a as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易圖通變","description":"易圖通變 - 易圖通變","frontmatter":{"title":"易圖通變","description":"易圖通變 - 易圖通變"},"headers":[],"relativePath":"classics/yitu-tongbian/001.md","filePath":"classics/yitu-tongbian/001.md"}'),i={name:"classics/yitu-tongbian/001.md"};function r(o,a,c,p,d,u){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"易圖通變",tabindex:"-1"},[s("易圖通變 "),e("a",{class:"header-anchor",href:"#易圖通變","aria-label":"Permalink to “易圖通變”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類易筮通變提要",-1),e("p",null,"臣 等謹案：易圖通變五卷，易筮通變三卷，宋雷思齊撰。思齊字齊賢，臨川人。宋亡之後，棄儒服為道士，居烏石觀。後終於廣信。事蹟具袁桷所撰墓誌銘。是編前有揭徯斯序，稱所著有老子本義、莊子旨義數十卷及和陶詩三卷。吳全節序又稱其有文集二十卷。今皆未見，惟此二書存。其易圖通變自序謂河圖之數，以八卦成列，相蕩相錯，恭天兩地，參伍以變其數實為四十，而以其十五會通於中。所述河圖洛書參天兩地倚數之圖、錯綜會變等圖，及河圖遺論，大旨以天一為坎，地二為坤，天三為震，地四為巽，天七為兌，地六為乾，天九為離，地八為艮，而五十則為虛數。其說雖與先儒不同，而按以出震齊巽之義，亦頗相脗合。林至易裨傅序所謂易道變化不窮，得其一端，皆足以為說者也。其易筮通變凡五篇，一曰卜筮，二曰立卦，三曰九六，四曰衍數，五曰命蓍，亦多自出新意，不主舊法。白雲霽道藏目錄載二書於太元部若字號中，蓋圖書之學，實出道家，思齊又本道士衍說之，以附於易，固亦有由雲。乾隆四十六年十二月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。欽定四庫全書易圖通變序：",-1),e("p",null,"道德數千言，吾教之所獨尊，古今未有能廢之者。然傳注層出，渺茫叢惑，莫適指歸，徒見多岐之紛紛也。雷思齊嗜學有要，精研是書，探核本旨，為之傳釋，合儒老之所同，歷詆其所異，條分緒別，終始一貫，不翅入老氏之室，避之席，以相授受也。其將學是者，終究其說，知其玄之玄，而不昧其所向，傳之將來，庶幾於吾教非小補也。至元丙辰，嗣天師簡齋張宗演序。",-1),e("p",null,"雷先生思齊，字齊賢，臨川之高士也。遭宋亡，獨居空山之中，著易圖筮通變義、老子本義、莊子旨義凡數十卷，和陶詩三卷。去儒服，稱黃冠師，與故淳安令曾公子良、今翰林學士吳公澄相友善。四方名士大夫慕其人，往往以書疏自通。或聞其講學，莫不爽然自失。故翰林侍講學士袁公桷，博雅君子也，稱其所著書援據精切，感厲奮發，合神以窮變，盡變以翼道。且曰：「知齊賢不如是，齊賢之意不明。」方今天下稱為斯文宗主，莫先吳公；天下稱善著書，莫先吳公。亦曰：「與談老子甚契。」又稱其詩精深工緻，豪健奇傑，有杜韓風。蓋皆以為知言。嗚呼！古稱虞卿非窮愁不能著書，太史公世掌天官，使不遇禍，史記不作。夫求雷先生之志，讀雷先生之書，遑與世俗道哉！遑與世俗道哉！餘讀其所著之書，想其為人幾五十年。今又得其詩文二十卷於其徒孫傅性真與周惟和傳入京師來，因識以辭。至順三年三月揭傒斯書昔世祖皇帝既定江南，首召三十六代天師入朝。未幾，天師奉旨掌道教還山，遂禮請先生為玄學講師，以訓迪後人。餘時雖幼，而有志於學，遂受學於先生。先生嘗誨餘曰：「文章於道，一技耳。人之為學，將以明斯道也。不明斯道，不足以為聖賢之學矣。」餘由是日知所省，益自奮發。及弱冠，入侍先師開府公於朝，遂不得事先生以終學焉。先生嘗注易圖筮通變義、老子本義、莊子旨義凡數十卷，詩文二十卷。至順二年秋，先生之徒弟傅性真遣徒孫周惟和持所著諸書來京師示餘，且曰：「先生所注之書，雖有黃公震、曾公子良、吳公澄為之序，而未得公一言以發明之，敢以為請。」餘曰：「嗟夫！先生之歿迨三十年矣，今不可得見，得見所注之書，斯可矣。然先生之學，豈所注之書可能盡哉？後之觀者考諸書，則知先生之學誠不止若是也。」餘今且老，久留於朝，常欲集先生諸文而序之，未果也。今諸文既已成編，又豈敢嘿嘿無一言以發明先生之學哉？故續為之序。先生諱思齊，字齊賢，學者尊之曰「空山先生」，撫之臨川人也。至順三年歲在壬申六月旦日，吳全節序。",-1),e("p",null,"河圖，八卦是也。圖之出，聖人則之。庖犧氏仰觀象，俯觀法，近取身，遠取物，以通神明之德，類萬物之情，始因之畫八卦以作易者也。孔子謂「其則之」，豈欺我哉？圖之數以八卦成列，相蕩相錯，參天兩地，參伍以變，皆自然而然。後世不本其數，實惟四十，而以其十五會通於中，乃妄計天地之數五十有五，以意增制於四十之外，以求其合，幸其中，故愈說愈迷，紛紛迄今。餘因潛心有年，備討眾說，獨識先聖之指歸，遂作通變傳，以與四方千載學易者，同究於真是焉。兼筮法亦乖素旨，附見後篇，求古同志，宜能明其非敢誣也。大元大德庚子九月，臨川道士雷思齊齊賢序。",-1)])])}const f=t(i,[["render",r]]);export{_ as __pageData,f as default};
